CREATE TABLE `users` (
  `id` varchar(36) NOT NULL,
  `email` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `organization_id` varchar(36) NOT NULL,
  `organization_name` varchar(255) NOT NULL,
  `role_id` varchar(36) NOT NULL,
  `role_name` varchar(255) NOT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_login` datetime DEFAULT NULL,
  `auth0_user_id` varchar(255) DEFAULT NULL,
  `email_verified` tinyint(1) DEFAULT '0',
  `password_set` tinyint(1) DEFAULT '0',
  `first_login_token` varchar(255) DEFAULT NULL,
  `assigned_project_ids` text,
  `assigned_apm_numbers` text,
  `theme_preference` varchar(20) DEFAULT 'system',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_email` (`email`),
  KEY `role_id` (`role_id`),
  KEY `idx_users_org` (`organization_id`),
  KEY `idx_users_first_login_token` (`first_login_token`),
  KEY `idx_users_auth0_user_id` (`auth0_user_id`),
  CONSTRAINT `users_ibfk_1` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `users_ibfk_2` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
